        const [scene_critical_x_left, scene_critical_x_right, scene_critical_y_up, scene_critical_y_down,] = this._get_bounding_box(mobjects, only_mobjects_in_frame);
        // calculate center x and y
        const x = (scene_critical_x_left + scene_critical_x_right) / 2;
        const y = (scene_critical_y_up + scene_critical_y_down) / 2;
